--region init
function StoreRecommend:InitData()
    local setting = CfUtils.GetCf(AutoIds.IdSetting603, "StoreRoleDialogueVo")
    ---@type StoreRoleDialogueVo[]
    local config = setting:GetAll()
    self._aniConfig = {}
    for i, v in ipairs(checkTable(config)) do
        if self._aniConfig[v.type] then
            table.insert(self._aniConfig[v.type], v)
        else
            self._aniConfig[v.type] = {v}
        end
    end
    
    local comp = StoreUtils.GetStoreComp()
    local dataKey = StoreConstants.Config[self._openId].dataKey
    local recommendData = comp.AllStores[dataKey]
    self._recommendList = recommendData.recommendList
    self._passCardScheduleId = recommendData.passCardScheduleId
end
--endregion init

--region handler
---看板娘点击回调
function StoreRecommend:BtnRoleClickHandler()
    if self.isLock then return end
    
    self:PlayRoleClickAnimation()
end

---看板娘spine动画结束处理
function StoreRecommend:SpineAnimationEndHandler(event)
    local name = event.Animation.Name
    if name ~= "idle" then
        self.isLock = false
        CfUtils.PlaySpine(self.Spine, "idle", true)
    end
end

