---刷新推荐列表
function StoreRecommend:OnRefreshIndex(listView, index, row, col)
    if index < 0 or index >= #self._recommendList  then
        return nil
    end
    local cell = listView:NewListViewItem(ListCell)
    local cellData = self._recommendList[index + 1]
    local chestData = StoreUtils.GetChestData(cellData.productId)
    if not chestData then return cell end
    local imgPath = StoreUtils.GetImageFullPath(chestData.image)
    CfUtils.FillImage(cell, imgPath)
    SetButtonAction(cell, function ()
        StoreUtils.OpenChestBuyDialog(StoreConstants.OpenIds.Gift, chestData)
        --StoreUtils.OpenStore(StoreConstants.OpenIds.Gift, nil, {itemData = chestData})
    end)
    return cell
end

---列表拖动结束事件处理
function StoreRecommend:OnEndDragHandler()
    local vec = self.AdvertisingFigure1.ScrollRect.velocity.x
    local curNearestItemIndex = self.AdvertisingFigure1.CurSnapNearestItemIndex
    local item = self.AdvertisingFigure1:GetShownItemByItemIndex(curNearestItemIndex)
    if isNull(item) then
        self.AdvertisingFigure1:ClearSnapData()
        return
    end
    if math.abs(vec) < 50 then
        self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex)
        return
    end

    local pos = self.AdvertisingFigure1:GetItemCornerPosInViewPort(item, CS.SuperScrollView.ItemCornerEnum.LeftTop)
    if pos.x > 0 then
        if vec > 0 then
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex)
        end
    elseif pos.x < 0 then
        if vec > 0 then
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex)
        else
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    else
        if vec > 0 then
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.AdvertisingFigure1:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    end
end


---列表变动事件处理
function StoreRecommend:OnSnapNearestChangedHandler(listView, item)
    self:UpdateListPage()
end

---定时器
function StoreRecommend:OnTimeTick()
    self._seconds = self._seconds + 1
    if self._seconds == 5 then
        self._seconds = 0
        local index = self.AdvertisingFigure1.CurSnapNearestItemIndex + 1
        if index == #self._recommendList then
            self.AdvertisingFigure1:SetSnapTargetItemIndex(0)
        else
            self.AdvertisingFigure1:SetSnapTargetItemIndex(index)
        end
    end
end

---商城页签切换事件处理
function StoreRecommend:TabOnClickEventHandler()
    self:StopVoice()
end
