function StoreRecommend:RefreshSelf(params)
    self._openId = params.openId
    self:InitData()
    self:PlayRoleEntryAnimation()
    self:RefreshPassCard()
    self:RefreshMonthlyCard()
    self:RefreshRecommendList()
end
