--region private
---播放看板娘进入动画
function StoreRecommend:PlayRoleEntryAnimation()
    local type = nil
    if self.isOpen then
        self.isOpen = false
        type = SpineAnimationType.OPEN
    else
        type = SpineAnimationType.SWITCH
    end
    self:PlayRoleAnimation(type)
end

---播放看板娘点击动画
function StoreRecommend:PlayRoleClickAnimation()
    local type = SpineAnimationType.CLICK
    self:PlayRoleAnimation(type)
end

---播放看板娘动画
---@param type  integer 动画类型
function StoreRecommend:PlayRoleAnimation(type)
    local index = math.random(1, #self._aniConfig[type])
    local data = self._aniConfig[type][index]
    self.isLock = true
    CfUtils.PlaySpine(self.Spine, data.action, false)
    CfUtils.FillText(self.TxtState, data.dialogue)
    CriWareUtils.PlayVoiceById(data.voicecode)
    self._voiceCode = data.voicecode
end

---刷新通行证
function StoreRecommend:RefreshPassCard()
    local conf = CfUtils.GetCfVo(AutoIds.IdSetting1501, "SeasonPassScheduleVo", self._passCardScheduleId)
    if not conf then return end
    CfUtils.FillImage(self.AdvertisingFigure2, conf.shopImg)
end

---刷新月卡
function StoreRecommend:RefreshMonthlyCard()
    local leftTime = StoreUtils.GetMonthlyCardLeftTime()
    KTool.SetActive(self.CountdownGroup, true)
    if leftTime then
        KTool.SetActive(self.MonthlyCardActive, true)
        KTool.SetActive(self.MonthlyCardNotActive, false)
        local day = math.floor(leftTime / 86400)
        CfUtils.FillText(self.TxtResidue, localize("剩余"))
        CfUtils.FillText(self.TxtNumber, day)
    else
        KTool.SetActive(self.MonthlyCardActive, false)
        KTool.SetActive(self.MonthlyCardNotActive, true)
    end
end

---刷新推荐页
function StoreRecommend:RefreshRecommendList()
    GameUtils.ReloadData(self.AdvertisingFigure1, #self._recommendList)
    self:RefreshPageList()
    
end

---刷新推荐列表底部页签
function StoreRecommend:RefreshPageList()
    for i, go in ipairs(self._pageList) do
        if not isNull(go) then
            GameObject.Destroy(go)
        end
    end

    self._pageList = {}
    for i = 1, #self._recommendList do
        local go = CfUtils.InstantiateGo(self.ImgSquare, self.PageGroup)
        KTool.SetActive(go, true)
        table.insert(self._pageList, go)
    end
    self:UpdateListPage()
end

function StoreRecommend:UpdateListPage()
    local curNearestItemIndex = self.AdvertisingFigure1.CurSnapNearestItemIndex
    if curNearestItemIndex < 0 or curNearestItemIndex >= #self._pageList then return end
    local index = curNearestItemIndex + 1
    for i, v in ipairs(self._pageList) do
        CfUtils.SetUISwitchImage(v, i == index and 1 or 2)
    end
end

---停止播放语音
function StoreRecommend:StopVoice()
    if not self._voiceCode then return end
    CriWareUtils.StopById(self._voiceCode)
    self._voiceCode = nil
end
